class Bettor {
  + name : string
  + balance : double
}

class Race {
  + id : int
  + winner : Runner
}

class Runner {
  + horseName : string
  + jockey : Jockey
}

class Jockey {
  + name : string
}

class Bet {
  + amount : double
  + odds : double
  + race : Race
  + runner : Runner
}

Bettor "1" -- "0..*" Bet
Race "1" -- "0..*" Bet
Runner "1" -- "0..*" Bet

@enduml

